mapper.select:
select count(1) count
from pay_fee_rule t
left join pay_fee_config pfc on t.config_id = pfc.config_id and pfc.status_cd = '0'
left join fee_type ft on pfc.ft_id = ft.ft_id and ft.status_cd = '0'
where 1 =1

    and t.max_time= #{maxTime}


    and t.amount= #{amount}


    and t.fee_type_cd= #{feeTypeCd}


    and t.cur_year_month= #{curYearMonth}


    and t.status_cd= #{statusCd}


    and t.batch_id= #{batchId}


    and t.income_obj_id= #{incomeObjId}


    and t.config_id= #{configId}


    and t.fee_flag= #{feeFlag}


    and t.start_time= #{startTime}


    and t.end_time= #{endTime}


    and t.state= #{state}


    and t.rule_id= #{ruleId}


    and t.community_id= #{communityId}


    and t.payer_obj_type= #{payerObjType}


    and t.payer_obj_id= #{payerObjId}


    and ft.ft_id= #{ftId}


    and ft.ft_name= #{ftName}

select t.rule_id ruleId, t.config_id configId, t.fee_type_cd feeTypeCd,
       t.fee_flag feeFlag, t.cur_year_month curYearMonth, t.amount,
       t.payer_obj_type payerObjType, t.payer_obj_id payerObjId,
       t.community_id communityId, t.state, t.fee_remark feeRemark,
       pfc.fee_name feeName
from pay_fee_rule t
left join pay_fee_config pfc on t.config_id = pfc.config_id and pfc.status_cd = '0'
where 1 = 1

    and t.community_id = #{communityId}


    and t.config_id = #{configId}


    and t.state = #{state}


    and t.fee_flag = #{feeFlag}


    and t.cur_year_month >= #{curYearMonthStart}


    and t.cur_year_month < #{curYearMonthEnd}

order by t.cur_year_month desc, t.create_time desc

    limit #{page}, #{row}

select count(1) count
from pay_fee_rule t
where 1 = 1

    and t.community_id = #{communityId}


    and t.config_id = #{configId}


    and t.state = #{state}


    and t.fee_flag = #{feeFlag}


    and t.cur_year_month >= #{curYearMonthStart}


    and t.cur_year_month < #{curYearMonthEnd}
